import{z as o,x as V,o as e,c as A,q as n,j as s,D as E,d as r,s as p,S as i,b as l}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"EUV 与自对准的混合","description":"","frontmatter":{"title":"EUV 与自对准的混合","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/euv-sapt-hybrid.md","filePath":"litho/euv-sapt-hybrid.md","lastUpdated":1791413859000}'),U={name:"litho/euv-sapt-hybrid.md"};function d(D,a,m,B,c,h){const t=V("Mermaid");return e(),A("div",null,[a[2]||(a[2]=n('<h1 id="euv-与自对准的混合" tabindex="-1">EUV 与自对准的混合 <a class="header-anchor" href="#euv-与自对准的混合" aria-label="Permalink to &quot;EUV 与自对准的混合&quot;">​</a></h1><div class="epigraph"><p>EUV 单次把一部分临界层从 DUV 多重里救出来；节距再往下，0.33 NA 的单次窗口又不够，于是 EUV 当芯轴或与 SAQP 叠在同一层策略里。</p><footer>—— 据晶圆厂与设备商对先进节点「EUV + 自对准多重」的公开层策略表述，不涉及产能与良率数字</footer></div><p><a href="/litho/duv-multipattern-cost">上一课</a>把浸没多重走到商品 7/5 nm 的代价写成过机次数、掩模、同层套刻与设计规则。缺口是：EUV 插入之后，并不是所有密层都改成一张版印完。单次 EUV 仍有 \\(k_1\\) 窗；更密的鳍、金属、孔会走上 EUV 双重、或 EUV 芯轴加 spacer。本课钉混合策略，不编 wph、片成本和成品率。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课的经济逻辑是：一张 EUV 替换两张或三张 DUV 分解，并去掉同层 LELE 套刻。这只覆盖「EUV 单次已经印得下」的层。0.33 NA、13.5 nm 的单次半节距仍受 \\(k_1\\) 地板约束；目标节距更小，就要把 EUV 当作 mandrel 光源去做 <a href="/litho/sadp-saqp">SADP/SAQP</a>，或对 EUV 再做 LELE 着色。公开节点叙事里，鳍长期走自对准、金属与孔逐步 EUV，再在更密世代把 EUV 与 spacer 叠起来，是层类型策略，不是「EUV 取代多重」的口号。</p><p><span class="marginnote">芯轴（mandrel）就是先印出来的那根「骨架」：先把骨架立起来，再在骨架侧面长出致密的侧墙，最后用侧墙当图形继续往下做。骨架本身不必是最终电路，它只负责提供一根整齐的侧壁当模具。</span></p><p>缺口因此是混合，而不是重算浸没 38–40 nm 单次极限。没有这层，会把「用了 NXE」写成整颗芯片不再有 cut 与 spacer。</p><h3 id="节点名仍不是波长" tabindex="-1">节点名仍不是波长 <a class="header-anchor" href="#节点名仍不是波长" aria-label="Permalink to &quot;节点名仍不是波长&quot;">​</a></h3><p>同一商品名下，有的层 EUV 单次，有的层 EUV+SADP，有的层仍浸没多重。讨论必须按层：mandrel 用哪台、切用哪台、孔是否三重。把某厂公开的「某代开始上 EUV」读成该代没有自对准，是把新闻稿当截面工艺。</p><p><span class="marginnote">High-NA（0.55）把单次窗口再拉开一截，公开定位是减少多重；在它覆盖不到或尚未导入的层上，混合策略仍然在。本课不把 EXE 写成已经取消 spacer。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>常见公开组合（按层，不点名良率）：浸没或 EUV 做 mandrel + spacer 做鳍或密金属；切层用 DUV LELE 或 EUV 单次，取决于切密度；通孔从 DUV 多重迁到 EUV 单次，再密则 EUV 双重。选择判据是拓扑（一维走 spacer，二维走 LELE/EUV）加上单次是否落在该波长的 \\(k_1\\) 窗内。</p><p><span class="marginnote">数字感受节距减半：芯轴节距 \\(80\\) nm 的阵列，长一层约 \\(40\\) nm 的侧墙再刻掉芯轴，图形节距就变成 \\(40\\) nm；再来一轮（SAQP）就是 \\(20\\) nm。所以最终鳍宽主要跟侧墙厚度与刻蚀走，而不是曝光机的名义分辨率。</span></p><p>混跑要求 DUV–EUV overlay 匹配，上一课已引用设备公开量级作为设备前提，不是良率。配方上，EUV mandrel 的 OPC 含掩模阴影；spacer 厚度预算与纯 DUV SADP 同类，walking 计量不因换波长消失。</p><h3 id="不要用-euv-单次-去承诺-spacer-后的鳍宽" tabindex="-1">不要用 EUV 单次 \\(k_1\\) 去承诺 spacer 后的鳍宽 <a class="header-anchor" href="#不要用-euv-单次-去承诺-spacer-后的鳍宽" aria-label="Permalink to &quot;不要用 EUV 单次 $k_1$ 去承诺 spacer 后的鳍宽&quot;">​</a></h3><p>最终鳍宽仍主要跟 \\(t\\) 与刻蚀走。EUV 只是把芯轴印得更密或更少多重，好让 spacer 轮数减少。把「EUV 分辨率」直接写成鳍 CD，是把光学半节距和薄膜 CD 混为一谈。</p>',16)),(e(),s(i,null,{default:E(()=>[p(t,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20EUV1%5B%22EUV%20%E5%8D%95%E6%AC%A1%E5%A4%9F%E7%94%A8%22%5D%20--%3E%20SWAP%5B%22%E6%9B%BF%E6%8D%A2%20DUV%20%E5%88%86%E8%A7%A3%E5%B1%82%22%5D%0A%20%20PITCH%5B%22%E8%8A%82%E8%B7%9D%E4%BB%8D%E4%BD%8E%E4%BA%8E%E5%8D%95%E6%AC%A1%E7%AA%97%22%5D%20--%3E%20HYB%5B%22EUV%20mandrel%20%E6%88%96%20EUV%20LELE%22%5D%0A%20%20HYB%20--%3E%20SP%5B%22%E5%86%8D%E5%8F%A0%E5%8A%A0%20SADP%2FSAQP%22%5D%0A%20%20HYB%20--%3E%20CUT%5B%22%E5%88%87%E5%B1%82%E4%BB%8D%E5%8F%AF%20DUV%20%E6%88%96%20EUV%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[r("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,"波长换栈改变的是芯轴或孔的空中像；自对准机制不换：侧墙仍贴侧壁，walking 仍是 core/gap，cut 仍吃 overlay。EUV 随机效应（光子与胶）会进入 mandrel LER，再保形到 spacer，这是附加误差源，不是 DUV 多重代价的简单平移。本课不量化随机良率。",-1)),(e(),s(i,null,{default:E(()=>[p(t,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20LR%0A%20%20M%5B%22EUV%20%E5%8D%B0%20mandrel%22%5D%20--%3E%20LER%5B%22mandrel%20LER%EF%BC%88%E5%90%AB%20EUV%20%E9%9A%8F%E6%9C%BA%EF%BC%89%22%5D%0A%20%20LER%20--%3E%20SP1%5B%22%E7%AC%AC%E4%B8%80%E5%B1%82%E4%BE%A7%E5%A2%99%E4%BF%9D%E5%BD%A2%E5%A4%8D%E5%88%B6%22%5D%0A%20%20SP1%20--%3E%20SP2%5B%22%E7%AC%AC%E4%BA%8C%E5%B1%82%E4%BE%A7%E5%A2%99%E5%86%8D%E5%A4%8D%E5%88%B6%22%5D%0A%20%20SP2%20--%3E%20FIN%5B%22%E9%B3%8D%20%2F%20%E5%AF%86%E9%87%91%E5%B1%9E%3A%20%E8%8A%82%E8%B7%9D%E5%87%8F%E5%8D%8A%E5%86%8D%E5%87%8F%E5%8D%8A%22%5D%0A%20%20CUT%5B%22%E5%88%87%E5%B1%82%E6%9B%9D%E5%85%89%22%5D%20--%3E%20OVL%5B%22%E5%90%83%20DUV-EUV%20overlay%22%5D%0A%20%20OVL%20--%3E%20ERR%5B%22%E5%88%87%E5%81%8F%20%3D%20%E7%9F%AD%E8%B7%AF%E6%88%96%E6%96%AD%E8%B7%AF%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p>这张图回答的是：混合流程里误差从哪来、传到哪。EUV 印得再准，最终鳍宽仍由侧墙链保形传递；切层则另吃一条套刻通道。</p><p>上一课把代价写成乘法。混合之后乘法还在，只是因子从「全 DUV 几次」变成「EUV 一次加 spacer 模块加切」。公开策略说的是哪一类层迁栈，不是一张可以外推到所有厂的产能表。</p><p>产能机制仍按模块乘：EUV 一次贵、浸没多次便宜，公开故事只说到层替换与机台分工，没有可抄的宇宙成本表。上一课禁止编的数字，本课继续禁止。</p><p><span class="marginnote">引用层策略时声明世代与层类型（鳍 / 金属 / 孔 / 切）。没有公开来源就不要写「某 nm 全部 SAQP+EUV」的清单。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>禁止：编造每小时晶圆、每层美元、7/5/3 nm 成品率、或未公开的掩模张数。允许：指出混合是产线公开方向——EUV 单次不够时与自对准或 EUV 多重叠用；浸没仍承担大量次临界与部分切层。中国产线与出口管制不在本课展开。</p><p><span class="marginnote">初学者容易以为「上了 EUV 就告别多重曝光」。实际上 EUV 多数时候只是把多重的轮数变少：原本浸没要打好几次的分解，换成 EUV 一次加一两轮侧墙。被省下的是过机次数，侧墙、walking 与切层套刻的机制一样不少。</span></p><p>后课进入 EUV 光源与设备课序时，默认读者已知道：NXE 不是自动取消 spacer 与 cut。</p><p><span class="marginnote">随机、缺陷、pellicle 会限制 EUV 单次实际窗口，使混合更早出现。那是 EUV 专项课的误差源，本课只承认它们会把「单次够不够」往保守推。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EUV 单次替换部分 DUV 分解；更密层仍要 EUV 多重或 EUV+SADP/SAQP。</li><li>混合按层选型：一维自对准，二维 EUV/LELE，切层独立。</li><li>Spacer 的 walking 与 cut 套刻不因换波长消失。</li><li>不编产能、成本与良率数字。</li><li>出处：先进节点公开层策略（EUV 与自对准共存）；上一课浸没多重代价结构。</li></ul>',11))])}const _=o(U,[["render",d]]);export{P as __pageData,_ as default};
